{"command":"$ErrorActionPreference = 'Stop'
$repo = 'edburns/dd-3070094-cargotracker-win32-x64-01'
$taskIssue = 2
$baseBranch = 'experiment/shepherd-control'
$body = @{ assignees = @('copilot-swe-agent[bot]'); agent_assignment = @{ target_repo = $repo; base_branch = $baseBranch } } | ConvertTo-Json -Depth 3
$assignmentOutput = @($body | gh api --method POST -H 'Accept: application/vnd.github+json' -H 'X-GitHub-Api-Version: 2022-11-28' "/repos/$repo/issues/$taskIssue/assignees" --input - 2>&1)
$code = $LASTEXITCODE
if ($code -ne 0) { throw "SHEPHERD FAILED: assignment exited $code`: $($assignmentOutput -join [Environment]::NewLine)" }
$deadline = [DateTimeOffset]::UtcNow.AddMinutes(15)
do {
  $timelineRaw = @(gh api "/repos/$repo/issues/$taskIssue/timeline?per_page=100" --paginate -H 'Accept: application/vnd.github+json' 2>$null)
  $code = $LASTEXITCODE
  if ($code -ne 0) { throw 'SHEPHERD FAILED: unable to query issue timeline.' }
  $timeline = ($timelineRaw -join [Environment]::NewLine) | ConvertFrom-Json
  $candidateNumbers = [System.Collections.Generic.HashSet[int]]::new()
  foreach ($event in @($timeline)) {
    if ($event.event -eq 'cross-referenced' -and $null -ne $event.source.issue.pull_request.url) {
      $url = [string]$event.source.issue.pull_request.url
      if ($url -match '/pulls/([1-9][0-9]*)$') { [void]$candidateNumbers.Add([int]$Matches[1]) }
    }
  }
  $matching = @()
  foreach ($candidate in $candidateNumbers) {
    $raw = @(gh pr view $candidate -R $repo --json state,isDraft,baseRefName,closingIssuesReferences 2>$null)
    $code = $LASTEXITCODE
    if ($code -ne 0) { throw "SHEPHERD FAILED: unable to verify candidate PR #$candidate." }
    $info = ($raw -join [Environment]::NewLine) | ConvertFrom-Json
    $closes = @($info.closingIssuesReferences | Where-Object { [int]$_.number -eq $taskIssue }).Count -gt 0
    if ($info.state -eq 'OPEN' -and $closes) { $matching += [pscustomobject]@{ number=$candidate; info=$info } }
  }
  if ($matching.Count -gt 1) { throw "SHEPHERD FAILED: multiple open PRs close task #$taskIssue." }
  if ($matching.Count -eq 1) {
    $match = $matching[0]
    if ($match.info.isDraft -ne $true -or $match.info.baseRefName -ne $baseBranch) { throw "SHEPHERD FAILED: linked PR #$($match.number) violated draft/base invariants." }
    Write-Output "PR_NUMBER=$($match.number)"
    break
  }
  Start-Sleep -Seconds 30
} while ([DateTimeOffset]::UtcNow -lt $deadline)
if ($matching.Count -ne 1) { throw 'SHEPHERD FAILED: no authoritative linked PR was found within 900 seconds.' }","description":"Assign issue and await linked PR","initial_wait":600,"mode":"sync"}

