From 2cebe179dc9e4a1facae9062e8e66bfd45cf57d7 Mon Sep 17 00:00:00 2001
From: "copilot-swe-agent[bot]" <198982749+Copilot@users.noreply.github.com>
Date: Mon, 28 Sep 2026 17:37:59 +0000
Subject: [PATCH 2/2] feat: add changeDeadline operation to booking service

Co-authored-by: edburns <75821+edburns@users.noreply.github.com>
---
 .../application/BookingService.java           |  2 ++
 .../internal/DefaultBookingService.java       | 15 ++++++++
 .../application/BookingServiceTest.java       | 35 +++++++++++++++++++
 3 files changed, 52 insertions(+)

diff --git [REDACTED].java [REDACTED].java
index 11b398e6..6f929a88 100644
--- [REDACTED].java
+++ [REDACTED].java
@@ -28,4 +28,6 @@ public interface BookingService {
     void assignCargoToRoute(Itinerary itinerary, TrackingId trackingId);

     void changeDestination(TrackingId trackingId, UnLocode unLocode);
+
+    void changeDeadline(TrackingId trackingId, Date deadline);
 }
diff --git [REDACTED].java [REDACTED].java
index aaa41c83..53c4d334 100644
--- [REDACTED].java
+++ [REDACTED].java
@@ -84,4 +84,19 @@ public void changeDestination(TrackingId trackingId, UnLocode unLocode) {
         logger.log(Level.INFO, "Changed destination for cargo {0} to {1}",
                 new Object[]{trackingId, routeSpecification.getDestination()});
     }
+
+    @Override
+    public void changeDeadline(TrackingId trackingId, Date deadline) {
+        Cargo cargo = cargoRepository.find(trackingId);
+
+        RouteSpecification routeSpecification = new RouteSpecification(
+                cargo.getOrigin(),
+                cargo.getRouteSpecification().getDestination(), deadline);
+        cargo.specifyNewRoute(routeSpecification);
+
+        cargoRepository.store(cargo);
+
+        logger.log(Level.INFO, "Changed deadline for cargo {0} to {1}",
+                new Object[]{trackingId, routeSpecification.getArrivalDeadline()});
+    }
 }
diff --git [REDACTED].java [REDACTED].java
index e77509a9..d7a4f18d 100644
--- [REDACTED].java
+++ [REDACTED].java
@@ -245,4 +245,39 @@ public void testChangeDestination() {
         assertEquals(RoutingStatus.MISROUTED, cargo.getDelivery()
                 .getRoutingStatus());
     }
+
+    @Test
+    @InSequence(5)
+    public void testChangeDeadline() {
+        GregorianCalendar calendar = new GregorianCalendar();
+        calendar.setTime(deadline);
+        calendar.add(Calendar.MONTH, 1); // One month later than the original.
+        Date newDeadline = calendar.getTime();
+
+        bookingService.changeDeadline(trackingId, newDeadline);
+
+        Cargo cargo = entityManager
+                .createNamedQuery("Cargo.findByTrackingId", Cargo.class)
+                .setParameter("trackingId", trackingId).getSingleResult();
+
+        assertEquals(SampleLocations.CHICAGO, cargo.getOrigin());
+        assertEquals(SampleLocations.HELSINKI, cargo.getRouteSpecification()
+                .getDestination());
+        assertTrue(DateUtils.isSameDay(newDeadline, cargo
+                .getRouteSpecification().getArrivalDeadline()));
+        assertEquals(assigned, cargo.getItinerary());
+        assertEquals(TransportStatus.NOT_RECEIVED, cargo.getDelivery()
+                .getTransportStatus());
+        assertEquals(Location.UNKNOWN, cargo.getDelivery()
+                .getLastKnownLocation());
+        assertEquals(Voyage.NONE, cargo.getDelivery().getCurrentVoyage());
+        assertFalse(cargo.getDelivery().isMisdirected());
+        assertEquals(Delivery.ETA_UNKOWN, cargo.getDelivery()
+                .getEstimatedTimeOfArrival());
+        assertEquals(Delivery.NO_ACTIVITY, cargo.getDelivery()
+                .getNextExpectedActivity());
+        assertFalse(cargo.getDelivery().isUnloadedAtDestination());
+        assertEquals(RoutingStatus.MISROUTED, cargo.getDelivery()
+                .getRoutingStatus());
+    }
 }

